# Expected values are SymPy's outputs for the same calls (Parsing (latex)).

skip_unless_full_tests()

skip_on_cran()

.bt <- new.env(parent = asNamespace("symcompR"))
eval(parse(text = r"---(x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z")
.fmt <- function(v) {
  f <- get0(".pe_str", envir = asNamespace("symcompR"))
  if (!is.null(f)) return(f(v))
  if (is.null(v)) "None" else if (inherits(v, "lark_tree")) format(v) else sstr(v)
}
.norm_err <- function(cls, msg) {
  lines <- strsplit(msg, "\n", fixed = TRUE)[[1L]]
  if (endsWith(msg, "\n")) lines <- c(lines, "")
  if (cls == "UnexpectedCharacters") {
    b <- startsWith(lines, "\t* ")
    rest <- lines[!b]
    lines <- c(rest[-length(rest)], sort(lines[b], method = "radix"), rest[length(rest)])
  }
  paste0("ERR ", cls, ": ", paste(lines, collapse = "\\n"))
}
.fmt1 <- function(v) paste(.fmt(v), collapse = "\n")
.err_msg <- function(e) {
  cls <- setdiff(class(e), c("simpleError", "error", "condition", "sympy_error"))
  m <- .norm_err(if (length(cls)) cls[1L] else "Error", conditionMessage(e))
  gsub("\\n", "\n", sub("^ERR [^:]*: ", "", m), fixed = TRUE)
}
)---"), envir = .bt)
.run <- function(code) {
  e <- new.env(parent = .bt)
  NULL
  get(".fmt1", envir = .bt)(eval(parse(text = code), envir = e))
}
.setup <- function(code) invisible(eval(parse(text = code), envir = .bt))
.err <- function(code) tryCatch({ .run(code); "no error" }, error = function(e) get(".err_msg", envir = .bt)(e))

test_that("Parsing (latex) match SymPy", {
  expect_equal(.run("parse_latex(\"x_0\", backend = \"lark\")"), "x_{0}")
  expect_equal(.run("parse_latex(\"x_{1}\", backend = \"lark\")"), "x_{1}")
  expect_equal(.run("parse_latex(\"x_a\", backend = \"lark\")"), "x_{a}")
  expect_equal(.run("parse_latex(\"x_{b}\", backend = \"lark\")"), "x_{b}")
  expect_equal(.run("parse_latex(\"h_\\\\theta\", backend = \"lark\")"), "h_{theta}")
  expect_equal(.run("parse_latex(\"h_{\\\\theta}\", backend = \"lark\")"), "h_{theta}")
  expect_equal(.run("parse_latex(\"y''_1\", backend = \"lark\")"), "y''_{1}")
  expect_equal(.run("parse_latex(\"y_1''\", backend = \"lark\")"), "y_{1}''")
  expect_equal(.run("parse_latex(\"\\\\mathit{x}\", backend = \"lark\")"), "x")
  expect_equal(.run("parse_latex(\"\\\\mathit{test}\", backend = \"lark\")"), "test")
  expect_equal(.run("parse_latex(\"\\\\mathit{TEST}\", backend = \"lark\")"), "TEST")
  expect_equal(.run("parse_latex(\"\\\\mathit{HELLO world}\", backend = \"lark\")"), "HELLO world")
  expect_equal(.run("parse_latex(\"a'\", backend = \"lark\")"), "a'")
  expect_equal(.run("parse_latex(\"a''\", backend = \"lark\")"), "a''")
  expect_equal(.run("parse_latex(\"\\\\alpha'\", backend = \"lark\")"), "alpha'")
  expect_equal(.run("parse_latex(\"\\\\alpha''\", backend = \"lark\")"), "alpha''")
  expect_equal(.run("parse_latex(\"a_b\", backend = \"lark\")"), "a_{b}")
  expect_equal(.run("parse_latex(\"a_b'\", backend = \"lark\")"), "a_{b}'")
  expect_equal(.run("parse_latex(\"a'_b\", backend = \"lark\")"), "a'_{b}")
